from artifact_tool_v2 import OverlapUnit, PresentationFile, warn_about_overlaps

# Its hard for the model to detect overlaps by just looking at a slide. `warn_about_overlaps`
# is a great tool to help the model detect overlaps. However, the model often refrains from
# calling it, even when prompted to.
# So we _always_ show warnings at the point when the presentation is exported. This behavior
# may need to be amended if we start using this library in other contexts.
if not hasattr(PresentationFile, "_export_pptx_original"):  # noqa: F405
    PresentationFile._export_pptx_original = PresentationFile.export_pptx  # noqa: F405

    @classmethod
    def _export_pptx_with_overlaps(
        cls,
        presentation,
        *,
        warn_about_overlaps_unit: OverlapUnit = "normalized_by_slide_dimensions",
    ):
        for slide_number, slide in enumerate(presentation.slides.items, start=1):
            warn_about_overlaps(
                slide,
                slide_number=slide_number,
                emit=True,
                overlap_unit=warn_about_overlaps_unit,
            )
        return cls._export_pptx_original(presentation)

    PresentationFile.export_pptx = _export_pptx_with_overlaps  # noqa: F405
